import { extractOverrides, flattenHeaders, generateMessageId, generateToolUseId, getContext, getTestId, isContentWithToolCallsResponse, isErrorResponse, isTextResponse, isToolCallResponse, resolveResponse, resolveStrictMode, strictOverrideField } from "./helpers.js";
import { matchFixture } from "./router.js";
import { calculateDelay, delay, writeErrorResponse } from "./sse-writer.js";
import { createInterruptionSignal } from "./interruption.js";
import { applyChaos } from "./chaos.js";
import { proxyAndRecord } from "./recorder.js";

//#region src/messages.ts
function extractClaudeTextContent(content) {
	if (typeof content === "string") return content;
	return content.filter((b) => b.type === "text").map((b) => b.text ?? "").join("");
}
function claudeToCompletionRequest(req) {
	const messages = [];
	if (req.system) {
		const systemText = typeof req.system === "string" ? req.system : req.system.filter((b) => b.type === "text").map((b) => b.text ?? "").join("");
		if (systemText) messages.push({
			role: "system",
			content: systemText
		});
	}
	for (const msg of req.messages) if (msg.role === "user") {
		if (typeof msg.content !== "string" && Array.isArray(msg.content)) {
			const toolResults = msg.content.filter((b) => b.type === "tool_result");
			const textBlocks = msg.content.filter((b) => b.type === "text");
			if (toolResults.length > 0) {
				for (const tr of toolResults) {
					const resultContent = typeof tr.content === "string" ? tr.content : Array.isArray(tr.content) ? tr.content.filter((b) => b.type === "text").map((b) => b.text ?? "").join("") : "";
					messages.push({
						role: "tool",
						content: resultContent,
						tool_call_id: tr.tool_use_id
					});
				}
				if (textBlocks.length > 0) messages.push({
					role: "user",
					content: textBlocks.map((b) => b.text ?? "").join("")
				});
				continue;
			}
		}
		messages.push({
			role: "user",
			content: extractClaudeTextContent(msg.content)
		});
	} else if (msg.role === "assistant") if (typeof msg.content === "string") messages.push({
		role: "assistant",
		content: msg.content
	});
	else if (Array.isArray(msg.content)) {
		const toolUseBlocks = msg.content.filter((b) => b.type === "tool_use");
		const textContent = extractClaudeTextContent(msg.content);
		if (toolUseBlocks.length > 0) messages.push({
			role: "assistant",
			content: textContent || null,
			tool_calls: toolUseBlocks.map((b) => ({
				id: b.id ?? generateToolUseId(),
				type: "function",
				function: {
					name: b.name ?? "",
					arguments: typeof b.input === "string" ? b.input : JSON.stringify(b.input ?? {})
				}
			}))
		});
		else messages.push({
			role: "assistant",
			content: textContent || null
		});
	} else messages.push({
		role: "assistant",
		content: null
	});
	let tools;
	if (req.tools && req.tools.length > 0) tools = req.tools.map((t) => ({
		type: "function",
		function: {
			name: t.name,
			description: t.description,
			parameters: t.input_schema
		}
	}));
	return {
		model: req.model,
		messages,
		stream: req.stream,
		temperature: req.temperature,
		max_tokens: req.max_tokens,
		tools,
		_endpointType: "chat"
	};
}
function claudeStopReason(finishReason, defaultReason) {
	if (!finishReason) return defaultReason;
	if (finishReason === "stop") return "end_turn";
	if (finishReason === "tool_calls") return "tool_use";
	if (finishReason === "length") return "max_tokens";
	return finishReason;
}
function claudeUsage(overrides) {
	if (!overrides?.usage) return {
		input_tokens: 0,
		output_tokens: 0
	};
	return {
		input_tokens: overrides.usage.input_tokens ?? overrides.usage.prompt_tokens ?? 0,
		output_tokens: overrides.usage.output_tokens ?? overrides.usage.completion_tokens ?? 0
	};
}
function buildClaudeTextStreamEvents(content, model, chunkSize, reasoning, overrides) {
	const msgId = overrides?.id ?? generateMessageId();
	const effectiveModel = overrides?.model ?? model;
	const events = [];
	events.push({
		type: "message_start",
		message: {
			id: msgId,
			type: "message",
			role: overrides?.role ?? "assistant",
			content: [],
			model: effectiveModel,
			stop_reason: null,
			stop_sequence: null,
			usage: claudeUsage(overrides)
		}
	});
	let blockIndex = 0;
	if (reasoning) {
		events.push({
			type: "content_block_start",
			index: blockIndex,
			content_block: {
				type: "thinking",
				thinking: "",
				signature: ""
			}
		});
		for (let i = 0; i < reasoning.length; i += chunkSize) {
			const slice = reasoning.slice(i, i + chunkSize);
			events.push({
				type: "content_block_delta",
				index: blockIndex,
				delta: {
					type: "thinking_delta",
					thinking: slice
				}
			});
		}
		events.push({
			type: "content_block_delta",
			index: blockIndex,
			delta: {
				type: "signature_delta",
				signature: ""
			}
		});
		events.push({
			type: "content_block_stop",
			index: blockIndex
		});
		blockIndex++;
	}
	events.push({
		type: "content_block_start",
		index: blockIndex,
		content_block: {
			type: "text",
			text: ""
		}
	});
	for (let i = 0; i < content.length; i += chunkSize) {
		const slice = content.slice(i, i + chunkSize);
		events.push({
			type: "content_block_delta",
			index: blockIndex,
			delta: {
				type: "text_delta",
				text: slice
			}
		});
	}
	events.push({
		type: "content_block_stop",
		index: blockIndex
	});
	events.push({
		type: "message_delta",
		delta: {
			stop_reason: claudeStopReason(overrides?.finishReason, "end_turn"),
			stop_sequence: null
		},
		usage: { output_tokens: claudeUsage(overrides).output_tokens }
	});
	events.push({ type: "message_stop" });
	return events;
}
function buildClaudeToolCallStreamEvents(toolCalls, model, chunkSize, logger, overrides) {
	const msgId = overrides?.id ?? generateMessageId();
	const effectiveModel = overrides?.model ?? model;
	const events = [];
	events.push({
		type: "message_start",
		message: {
			id: msgId,
			type: "message",
			role: overrides?.role ?? "assistant",
			content: [],
			model: effectiveModel,
			stop_reason: null,
			stop_sequence: null,
			usage: claudeUsage(overrides)
		}
	});
	for (let idx = 0; idx < toolCalls.length; idx++) {
		const tc = toolCalls[idx];
		const toolUseId = tc.id || generateToolUseId();
		let argsObj;
		try {
			argsObj = JSON.parse(tc.arguments || "{}");
		} catch {
			logger.warn(`Malformed JSON in fixture tool call arguments for "${tc.name}": ${tc.arguments}`);
			argsObj = {};
		}
		const argsJson = JSON.stringify(argsObj);
		events.push({
			type: "content_block_start",
			index: idx,
			content_block: {
				type: "tool_use",
				id: toolUseId,
				name: tc.name,
				input: {}
			}
		});
		for (let i = 0; i < argsJson.length; i += chunkSize) {
			const slice = argsJson.slice(i, i + chunkSize);
			events.push({
				type: "content_block_delta",
				index: idx,
				delta: {
					type: "input_json_delta",
					partial_json: slice
				}
			});
		}
		events.push({
			type: "content_block_stop",
			index: idx
		});
	}
	events.push({
		type: "message_delta",
		delta: {
			stop_reason: claudeStopReason(overrides?.finishReason, "tool_use"),
			stop_sequence: null
		},
		usage: { output_tokens: claudeUsage(overrides).output_tokens }
	});
	events.push({ type: "message_stop" });
	return events;
}
function buildClaudeTextResponse(content, model, reasoning, overrides) {
	const contentBlocks = [];
	if (reasoning) contentBlocks.push({
		type: "thinking",
		thinking: reasoning,
		signature: ""
	});
	contentBlocks.push({
		type: "text",
		text: content
	});
	return {
		id: overrides?.id ?? generateMessageId(),
		type: "message",
		role: overrides?.role ?? "assistant",
		content: contentBlocks,
		model: overrides?.model ?? model,
		stop_reason: claudeStopReason(overrides?.finishReason, "end_turn"),
		stop_sequence: null,
		usage: claudeUsage(overrides)
	};
}
function buildClaudeToolCallResponse(toolCalls, model, logger, overrides) {
	return {
		id: overrides?.id ?? generateMessageId(),
		type: "message",
		role: overrides?.role ?? "assistant",
		content: toolCalls.map((tc) => {
			let argsObj;
			try {
				argsObj = JSON.parse(tc.arguments || "{}");
			} catch {
				logger.warn(`Malformed JSON in fixture tool call arguments for "${tc.name}": ${tc.arguments}`);
				argsObj = {};
			}
			return {
				type: "tool_use",
				id: tc.id || generateToolUseId(),
				name: tc.name,
				input: argsObj
			};
		}),
		model: overrides?.model ?? model,
		stop_reason: claudeStopReason(overrides?.finishReason, "tool_use"),
		stop_sequence: null,
		usage: claudeUsage(overrides)
	};
}
